package app.gtdial.lab;

import android.net.Uri;
import org.json.JSONObject;
import org.json.JSONArray;
import java.io.File;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.function.BiConsumer;

/** Photo proposals are editable local drafts; this controller can never confirm an entry. */
final class NutritionPhotoController {
    private static final ExecutorService IMAGES=Executors.newSingleThreadExecutor();
    private final android.os.Handler main=new android.os.Handler(android.os.Looper.getMainLooper());
    private final NutritionImagePreparer preparer;private final OpenRouterClient client;private volatile int generation;private File preview;
    NutritionPhotoController(android.content.Context context,OpenRouterClient client){preparer=new NutritionImagePreparer(context);this.client=client;IMAGES.execute(preparer::cleanup);}
    File preview(){return preview;}
    void prepare(Uri uri,BiConsumer<File,String> done){cancel();int expected=generation;IMAGES.execute(()->{File file=null;String error="";try{file=preparer.prepare(uri);}catch(Exception e){error="PHOTO_PREPARATION_FAILED";}File prepared=file;String failure=error;main.post(()->{if(expected!=generation){if(prepared!=null)IMAGES.execute(()->preparer.discard(prepared));return;}preview=prepared;done.accept(prepared,failure);});});}
    void send(String model,BiConsumer<JSONArray,String> done){File exact=preview;if(exact==null){done.accept(null,"PHOTO_PREVIEW_REQUIRED");return;}int expected=generation;long credential=client.credentials.revision();IMAGES.execute(()->{JSONObject body=null;String error="";try{String image="data:image/jpeg;base64,"+android.util.Base64.encodeToString(preparer.bytes(exact),android.util.Base64.NO_WRAP);body=client.body(model,true,NutritionModels.object("locale","ru"),image,schema());}catch(Exception e){error=e instanceof RuntimeException?AnalysisController.safe((RuntimeException)e):"PHOTO_PREPARATION_FAILED";}JSONObject request=body;String failed=error;main.post(()->{if(expected!=generation||credential!=client.credentials.revision())return;if(!failed.isEmpty()){done.accept(null,failed);return;}client.complete(request,true,(response,networkError)->{if(expected!=generation||credential!=client.credentials.revision())return;if(!networkError.isEmpty()){done.accept(null,networkError);return;}try{AnalysisResponseValidator.validateSchema(response,schema(),0);JSONArray proposals=response.optJSONArray("items"),items=new JSONArray();long at=System.currentTimeMillis();for(int i=0;i<proposals.length();i++){JSONObject value=proposals.optJSONObject(i),item=NutritionModels.item();NutritionModels.put(item,"name",value.optString("name"));NutritionModels.put(item,"quantityMilli",value.opt("quantityMilli"));NutritionModels.put(item,"inputMethod","PHOTO");for(String key:NutritionModels.NUTRIENTS)NutritionModels.put(item,key,value.opt(key));NutritionModels.put(item,"originalEstimate",NutritionModels.object("quantityMilli",value.opt("quantityMilli"),"kcalMilli",value.opt("kcalMilli"),"proteinMg",value.opt("proteinMg"),"fatMg",value.opt("fatMg"),"carbohydrateMg",value.opt("carbohydrateMg")));NutritionModels.put(item,"provenance",NutritionModels.object("kind","PHOTO_ESTIMATE","model",model,"estimatedAt",at,"assumptions",value.optJSONArray("assumptions"),"kcalLowMilli",value.opt("kcalLowMilli"),"kcalHighMilli",value.opt("kcalHighMilli")));NutritionModels.validateItem(item);items.put(item);}done.accept(items,"");}catch(RuntimeException e){done.accept(null,"PHOTO_RESPONSE_INVALID");}});});});}
    void cancel(){generation++;client.cancel();File previous=preview;preview=null;if(previous!=null)IMAGES.execute(()->preparer.discard(previous));}
    void pause(){generation++;client.cancel();}
    static JSONObject schema(){JSONObject number=NutritionModels.object("type",new JSONArray().put("integer").put("null"),"minimum",0,"maximum",NutritionModels.MAX_KCAL);JSONObject quantity=NutritionModels.object("type",new JSONArray().put("integer").put("null"),"minimum",1,"maximum",NutritionModels.MAX_QUANTITY);JSONObject properties=NutritionModels.object("name",NutritionModels.object("type","string","minLength",1,"maxLength",160),"quantityMilli",quantity,"kcalMilli",number,"proteinMg",number,"fatMg",number,"carbohydrateMg",number,"kcalLowMilli",number,"kcalHighMilli",number,"assumptions",NutritionModels.object("type","array","maxItems",8,"items",NutritionModels.object("type","string","maxLength",240,"minLength",1)));JSONArray required=new JSONArray();for(String key:NutritionModels.fieldNames(properties))required.put(key);JSONObject item=NutritionModels.object("type","object","properties",properties,"required",required,"additionalProperties",false);return NutritionModels.object("type","object","properties",NutritionModels.object("items",NutritionModels.object("type","array","minItems",1,"maxItems",32,"items",item)),"required",new JSONArray().put("items"),"additionalProperties",false);}
}

